-- NEXORA FORGE ACADEMY CMS
-- Run once in Supabase SQL Editor for project ufranjjvhmsrkoxtlqcl.
create table if not exists public.academy_courses (
 id text primary key,
 title text not null check (char_length(title) between 2 and 120),
 description text not null default '',
 level text not null default 'مقدماتی',
 sort_order int not null default 0,
 is_published boolean not null default true,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create table if not exists public.academy_lessons (
 id text primary key,
 course_id text not null references public.academy_courses(id) on delete cascade,
 title text not null check (char_length(title) between 2 and 180),
 content_html text not null default '',
 starter_code text not null default '',
 exercise text not null default '',
 sort_order int not null default 0,
 is_published boolean not null default true,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index if not exists academy_lessons_course_order_idx on public.academy_lessons(course_id,sort_order);
alter table public.academy_courses enable row level security;
alter table public.academy_lessons enable row level security;
drop policy if exists "Public reads published academy courses" on public.academy_courses;
create policy "Public reads published academy courses" on public.academy_courses for select to anon,authenticated using (is_published or public.is_academy_admin());
drop policy if exists "Admins manage academy courses" on public.academy_courses;
create policy "Admins manage academy courses" on public.academy_courses for all to authenticated using (public.is_academy_admin()) with check (public.is_academy_admin());
drop policy if exists "Public reads published academy lessons" on public.academy_lessons;
create policy "Public reads published academy lessons" on public.academy_lessons for select to anon,authenticated using (is_published or public.is_academy_admin());
drop policy if exists "Admins manage academy lessons" on public.academy_lessons;
create policy "Admins manage academy lessons" on public.academy_lessons for all to authenticated using (public.is_academy_admin()) with check (public.is_academy_admin());
grant select on public.academy_courses,public.academy_lessons to anon,authenticated;
grant insert,update,delete on public.academy_courses,public.academy_lessons to authenticated;

-- Limited student overview for admins. No passwords or authentication tokens are exposed.
create or replace function public.academy_admin_student_overview()
returns table(user_id uuid,email text,created_at timestamptz,completed_lessons integer,quiz_attempts bigint)
language plpgsql stable security definer set search_path=public,auth
as $$
begin
 if not public.is_academy_admin() then raise exception 'not authorized'; end if;
 return query
 select u.id,u.email,u.created_at,
        coalesce(cardinality(p.completed_lessons),0),
        (select count(*) from public.student_quiz_attempts q where q.user_id=u.id)
 from auth.users u
 left join public.student_progress p on p.user_id=u.id
 order by u.created_at desc
 limit 200;
end $$;
revoke all on function public.academy_admin_student_overview() from public,anon;
grant execute on function public.academy_admin_student_overview() to authenticated;

insert into public.academy_courses(id,title,description,level,sort_order,is_published) values
('html','HTML — ساختار وب','ساختار معنایی صفحات، فرم‌ها، رسانه و دسترس‌پذیری.','مقدماتی',1,true),
('css','CSS — طراحی وب','رنگ، تایپوگرافی، مدل جعبه‌ای، Flexbox، Grid و واکنش‌گرایی.','مقدماتی تا متوسط',2,true),
('js','JavaScript — منطق وب','داده، شرط، حلقه، تابع، DOM، رویداد و ذخیره‌سازی مرورگر.','مقدماتی تا متوسط',3,true)
on conflict(id) do update set title=excluded.title,description=excluded.description,level=excluded.level,sort_order=excluded.sort_order;

-- Import the complete authored 58-lesson curriculum, preserving detailed lesson text and examples from app.js.
with seed as (
 select * from jsonb_to_recordset($academy_seed$[{"id":"html:0","course_id":"html","title":"HTML چیست؟","content_html":"<p>HTML مخفف HyperText Markup Language است. با آن ساختار محتوای یک صفحه وب را مشخص می‌کنیم؛ مثلاً عنوان، پاراگراف، تصویر و لینک.</p><ul><li>HTML زبان نشانه‌گذاری است، نه زبان برنامه‌نویسی.</li><li>مرورگر تگ‌ها را می‌خواند و محتوا را نمایش می‌دهد.</li></ul>","starter_code":"<h1>سلام دنیا</h1>\n<p>این اولین صفحه من است.</p>","exercise":"یک صفحه ساده بساز که عنوان «آکادمی من» و یک پاراگراف معرفی داشته باشد.","sort_order":0},{"id":"html:1","course_id":"html","title":"ساختار استاندارد صفحه","content_html":"<p>هر سند HTML با اعلام نوع سند شروع می‌شود. عنصر html ریشه صفحه است، head اطلاعات صفحه را نگه می‌دارد و body محتوای قابل مشاهده را.</p>","starter_code":"<!doctype html>\n<html lang=\"fa\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>صفحه من</title>\n</head>\n<body>\n  <h1>سلام!</h1>\n</body>\n</html>","exercise":"یک سند کامل HTML با lang فارسی، charset، عنوان صفحه و بخش body بساز.","sort_order":1},{"id":"html:2","course_id":"html","title":"عنوان‌ها و پاراگراف‌ها","content_html":"<p>برای عنوان‌ها از h1 تا h6 استفاده می‌شود. تگ p برای پاراگراف است. عنوان‌ها باید ترتیب منطقی داشته باشند و فقط برای بزرگ کردن متن استفاده نشوند.</p>","starter_code":"<h1>عنوان اصلی</h1>\n<h2>عنوان بخش</h2>\n<p>این یک پاراگراف است.</p>","exercise":"برای یک مقاله، یک عنوان اصلی، دو عنوان فرعی و سه پاراگراف ایجاد کن.","sort_order":2},{"id":"html:3","course_id":"html","title":"لینک‌ها","content_html":"<p>تگ a برای ساخت لینک است. آدرس مقصد را در ویژگی href قرار می‌دهیم. برای باز کردن لینک در زبانه جدید از target استفاده می‌شود و بهتر است rel نیز تنظیم شود.</p>","starter_code":"<a href=\"https://example.com\">بازدید از سایت</a>\n<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\">در زبانه جدید</a>","exercise":"یک لینک به سایت دلخواه و یک لینک که در زبانه جدید باز شود بساز.","sort_order":3},{"id":"html:4","course_id":"html","title":"تصاویر و متن جایگزین","content_html":"<p>تگ img تصویر را نمایش می‌دهد. ویژگی src مسیر تصویر و alt توضیح متنی تصویر است. متن alt برای دسترس‌پذیری و زمانی که تصویر بارگذاری نشود اهمیت دارد.</p>","starter_code":"<img src=\"photo.jpg\" alt=\"نمایی از طبیعت\" width=\"300\">","exercise":"یک تصویر اضافه کن و برای آن alt توصیفی و عرض ۲۵۰ پیکسل تعیین کن.","sort_order":4},{"id":"html:5","course_id":"html","title":"فهرست‌ها","content_html":"<p>برای فهرست بدون ترتیب از ul و برای فهرست شماره‌دار از ol استفاده کن. هر مورد فهرست داخل li قرار می‌گیرد.</p>","starter_code":"<ul>\n  <li>HTML</li>\n  <li>CSS</li>\n</ul>\n<ol>\n  <li>یادگیری</li>\n  <li>تمرین</li>\n</ol>","exercise":"فهرست شماره‌دار سه مرحله‌ای و فهرست بدون ترتیب سه مهارت بساز.","sort_order":5},{"id":"html:6","course_id":"html","title":"عناصر معنایی HTML","content_html":"<p>عناصر معنایی نامی دارند که نقش محتوا را روشن می‌کند. header برای سربرگ، nav برای ناوبری، main برای محتوای اصلی، section برای بخش و footer برای پابرگ مناسب است.</p><p>از این عناصر به‌جای استفاده بی‌دلیل از div استفاده کن تا ساختار صفحه برای مرورگرها و ابزارهای کمکی قابل فهم‌تر باشد.</p>","starter_code":"<header>سربرگ سایت</header>\n<nav><a href='#home'>خانه</a></nav>\n<main>\n  <section><h2>درباره ما</h2><p>متن بخش</p></section>\n</main>\n<footer>پابرگ</footer>","exercise":"صفحه‌ای با header، nav، main، section و footer بساز.","sort_order":6},{"id":"html:7","course_id":"html","title":"ساخت فرم","content_html":"<p>فرم‌ها اطلاعات را از کاربر می‌گیرند. عنصر form محدوده فرم را می‌سازد و label عنوان هر ورودی را مشخص می‌کند. ویژگی for در label باید با id ورودی برابر باشد.</p>","starter_code":"<form>\n  <label for='fullname'>نام:</label>\n  <input id='fullname' name='fullname'>\n  <button type='submit'>ارسال</button>\n</form>","exercise":"فرمی با ورودی نام و دکمه ارسال بساز و label مرتبط اضافه کن.","sort_order":7},{"id":"html:8","course_id":"html","title":"انواع ورودی‌ها","content_html":"<p>ویژگی type نوع ورودی را مشخص می‌کند. email برای ایمیل، password برای رمز، number برای عدد، date برای تاریخ و checkbox برای انتخاب روشن/خاموش کاربرد دارند.</p><p>برای هر ورودی یک label قابل کلیک فراهم کن و در صورت نیاز از required استفاده کن.</p>","starter_code":"<label for='email'>ایمیل</label>\n<input id='email' type='email' required>\n<label for='age'>سن</label>\n<input id='age' type='number' min='1' max='120'>\n<label><input type='checkbox'> قوانین را می‌پذیرم</label>","exercise":"ورودی ایمیل، رمز عبور، تاریخ و checkbox ایجاد کن.","sort_order":8},{"id":"html:9","course_id":"html","title":"دکمه‌ها و ارسال فرم","content_html":"<p>دکمه داخل فرم به‌طور پیش‌فرض ممکن است فرم را ارسال کند. type='submit' برای ارسال و type='button' برای عملیاتی که نباید فرم را ارسال کند استفاده می‌شود.</p>","starter_code":"<form action='/register' method='post'>\n  <input name='username' required>\n  <button type='submit'>ثبت‌نام</button>\n  <button type='button' onclick='alert('سلام')'>نمایش پیام</button>\n</form>","exercise":"فرمی بساز که دکمه ارسال و دکمه عادی با عملکرد متفاوت داشته باشد.","sort_order":9},{"id":"html:10","course_id":"html","title":"جدول‌ها","content_html":"<p>برای داده‌های جدولی از table استفاده کن. tr ردیف، th عنوان ستون و td خانه داده است. caption عنوان جدول را می‌دهد و thead و tbody بخش‌های جدول را جدا می‌کنند.</p>","starter_code":"<table>\n  <caption>نمره‌ها</caption>\n  <thead><tr><th>نام</th><th>نمره</th></tr></thead>\n  <tbody><tr><td>سارا</td><td>۱۸</td></tr></tbody>\n</table>","exercise":"جدولی با سه ستون نام، درس و نمره و حداقل دو ردیف داده بساز.","sort_order":10},{"id":"html:11","course_id":"html","title":"صدا و ویدیو","content_html":"<p>عناصر audio و video برای پخش رسانه هستند. ویژگی controls کنترل‌های پخش را نمایش می‌دهد. می‌توان چند source با قالب‌های متفاوت تعریف کرد تا مرورگر گزینه سازگار را انتخاب کند.</p>","starter_code":"<video controls width='320'>\n  <source src='movie.mp4' type='video/mp4'>\n  مرورگر شما از ویدیو پشتیبانی نمی‌کند.\n</video>\n<audio controls src='sound.mp3'></audio>","exercise":"یک عنصر video با controls و متن جایگزین در صورت پشتیبانی‌نشدن اضافه کن.","sort_order":11},{"id":"html:12","course_id":"html","title":"ویژگی‌های عمومی و data","content_html":"<p>ویژگی‌هایی مانند id و class روی عناصر مختلف قابل استفاده‌اند. id باید در صفحه یکتا باشد؛ class برای گروهی از عناصر مناسب است. ویژگی‌های data-* برای نگهداری داده‌های سفارشی در HTML هستند.</p>","starter_code":"<article id='lesson-1' class='card' data-level='beginner'>\n  <h2>درس اول</h2>\n  <p>شروع یادگیری</p>\n</article>","exercise":"برای یک کارت id، class و data-level تعریف کن.","sort_order":12},{"id":"html:13","course_id":"html","title":"div و span","content_html":"<p>div یک ظرف بلوکی عمومی و span یک ظرف درون‌خطی عمومی است. وقتی عنصر معنایی مناسب وجود ندارد، از آن‌ها برای گروه‌بندی و استایل‌دهی استفاده کن؛ نه اینکه همه صفحه را با div بسازی.</p>","starter_code":"<div class='profile'>\n  <h2>مشخصات</h2>\n  <p>نام: <span class='highlight'>علی</span></p>\n</div>","exercise":"با div دو بخش بساز و با span یک کلمه را درون پاراگراف مشخص کن.","sort_order":13},{"id":"html:14","course_id":"html","title":"دسترس‌پذیری و HTML درست","content_html":"<p>برای دسترس‌پذیری، تصویر معنادار باید alt مناسب داشته باشد، فرم‌ها label داشته باشند، ترتیب عنوان‌ها منطقی باشد و لینک‌ها متن توصیفی داشته باشند. از عنصر درست برای کار درست استفاده کن.</p>","starter_code":"<img src='team.jpg' alt='اعضای تیم در جلسه کاری'>\n<h1>آموزش وب</h1>\n<h2>درس‌های رایگان</h2>\n<a href='/courses'>مشاهده دوره‌های آموزشی</a>","exercise":"برای تصویر alt، برای ورودی label و برای دکمه متن واضح قرار بده.","sort_order":14},{"id":"css:0","course_id":"css","title":"CSS چیست؟","content_html":"<p>CSS مخفف Cascading Style Sheets است و ظاهر عناصر HTML را کنترل می‌کند؛ مانند رنگ، اندازه، فاصله و چیدمان.</p><p>قانون CSS از انتخابگر و مجموعه‌ای از ویژگی‌ها و مقدارها تشکیل می‌شود.</p>","starter_code":"h1 {\n  color: crimson;\n  font-size: 32px;\n}","exercise":"رنگ عنوان را قرمز و اندازه آن را ۳۲ پیکسل کن.","sort_order":0},{"id":"css:1","course_id":"css","title":"سه روش افزودن CSS","content_html":"<p>CSS را می‌توان در ویژگی style، داخل تگ style یا در فایل جداگانه با پسوند css نوشت. برای پروژه‌های واقعی، فایل جداگانه معمولاً نگهداری را ساده‌تر می‌کند.</p>","starter_code":"<!-- در فایل HTML -->\n<link rel=\"stylesheet\" href=\"style.css\">\n\n/* در فایل style.css */\nbody { font-family: Arial; }","exercise":"یک فایل style.css بساز و آن را به فایل HTML وصل کن.","sort_order":1},{"id":"css:2","course_id":"css","title":"انتخابگرها","content_html":"<p>انتخابگر مشخص می‌کند کدام عنصر استایل بگیرد. نام تگ، کلاس با نقطه و شناسه با # انتخابگرهای رایج هستند.</p>","starter_code":"p { color: #444; }\n.card { padding: 16px; }\n#main-title { color: red; }","exercise":"با انتخابگر تگ، کلاس و شناسه سه عنصر متفاوت را استایل بده.","sort_order":2},{"id":"css:3","course_id":"css","title":"رنگ و پس‌زمینه","content_html":"<p>رنگ را می‌توان با نام، کد HEX یا تابع rgb مشخص کرد. ویژگی background-color رنگ پس‌زمینه را تعیین می‌کند.</p>","starter_code":"body { background-color: #101018; }\nh1 { color: #ff303b; }\n.note { color: rgb(180,180,190); }","exercise":"برای صفحه پس‌زمینه تیره و برای متن رنگ روشن انتخاب کن.","sort_order":3},{"id":"css:4","course_id":"css","title":"مدل جعبه‌ای","content_html":"<p>هر عنصر در CSS مانند یک جعبه است: محتوا، padding، border و margin. استفاده از box-sizing: border-box محاسبه اندازه‌ها را قابل پیش‌بینی‌تر می‌کند.</p>","starter_code":"* { box-sizing: border-box; }\n.card {\n  padding: 20px;\n  border: 1px solid #ccc;\n  margin: 12px;\n}","exercise":"یک کارت با padding، border و margin بساز و box-sizing را تنظیم کن.","sort_order":4},{"id":"css:5","course_id":"css","title":"Flexbox و واکنش‌گرایی","content_html":"<p>Flexbox برای چیدمان یک‌بعدی کاربرد دارد. با media query می‌توان ظاهر صفحه را برای نمایشگرهای کوچک تغییر داد.</p>","starter_code":".row { display: flex; gap: 12px; }\n@media (max-width: 600px) {\n  .row { flex-direction: column; }\n}","exercise":"سه کارت را با Flexbox کنار هم بچین و در عرض کمتر از ۶۰۰ پیکسل ستونی کن.","sort_order":5},{"id":"css:6","course_id":"css","title":"آبشار و وراثت CSS","content_html":"<p>وقتی چند قانون روی یک عنصر اثر می‌گذارند، آبشار CSS با توجه به اهمیت، اختصاصیت و ترتیب قوانین تصمیم می‌گیرد کدام مقدار اعمال شود. بعضی ویژگی‌ها مانند color به فرزندان به ارث می‌رسند.</p>","starter_code":"body { color: #333; }\n.card { color: #b21e35; }\n.card p { color: inherit; }","exercise":"رنگ متن body را تعیین کن و رنگ یک عنصر فرزند را جداگانه تغییر بده.","sort_order":6},{"id":"css:7","course_id":"css","title":"اختصاصیت انتخابگرها","content_html":"<p>انتخابگر id معمولاً از class اختصاصی‌تر است و class از انتخابگر نام تگ اختصاصی‌تر. برای جلوگیری از پیچیدگی، تا حد ممکن از کلاس‌های قابل استفاده مجدد استفاده کن و به !important وابسته نشو.</p>","starter_code":"p { color: gray; }\n.note { color: crimson; }\n#intro { color: navy; }","exercise":"برای یک عنصر قانون تگ، کلاس و شناسه بنویس و نتیجه را مقایسه کن.","sort_order":7},{"id":"css:8","course_id":"css","title":"واحدهای اندازه‌گیری","content_html":"<p>px واحد ثابت، درصد نسبی به اندازه والد، em وابسته به اندازه فونت عنصر والد و rem وابسته به اندازه فونت ریشه است. برای اندازه‌های قابل تطبیق معمولاً rem و درصد انتخاب‌های مناسبی‌اند.</p>","starter_code":"html { font-size: 16px; }\nh1 { font-size: 2rem; }\n.container { width: 90%; max-width: 1100px; }\n.card { padding: 1em; }","exercise":"یک کارت با rem برای فونت و درصد برای عرض بساز.","sort_order":8},{"id":"css:9","course_id":"css","title":"فونت و خوانایی متن","content_html":"<p>با font-family نوع قلم، font-size اندازه، font-weight ضخامت و line-height فاصله خطوط را کنترل می‌کنی. برای متن فارسی، قلم مناسب و فاصله خطوط کافی خوانایی را بهتر می‌کند.</p>","starter_code":"body { font-family: Tahoma, Arial, sans-serif; }\np { font-size: 16px; line-height: 1.9; }\nh1 { font-weight: 800; }","exercise":"برای متن فارسی فونت مناسب، line-height و اندازه خوانا تنظیم کن.","sort_order":9},{"id":"css:10","course_id":"css","title":"display و جریان عناصر","content_html":"<p>display رفتار چیدمان عنصر را تعیین می‌کند. block تمام عرض در دسترس را می‌گیرد، inline در جریان متن قرار می‌گیرد، inline-block امکان تعیین ابعاد را می‌دهد و none عنصر را از چیدمان حذف می‌کند.</p>","starter_code":".badge { display: inline-block; padding: 6px 10px; }\n.hidden { display: none; }\n.card { display: block; }","exercise":"دو عنصر را با inline-block کنار هم قرار بده و تفاوت block را بررسی کن.","sort_order":10},{"id":"css:11","course_id":"css","title":"موقعیت‌دهی عناصر","content_html":"<p>position با مقادیر static، relative، absolute، fixed و sticky موقعیت عنصر را کنترل می‌کند. absolute نسبت به نزدیک‌ترین والد موقعیت‌دار محاسبه می‌شود؛ sticky هنگام پیمایش می‌تواند به لبه صفحه بچسبد.</p>","starter_code":".parent { position: relative; }\n.label { position: absolute; top: 8px; right: 8px; }\nheader { position: sticky; top: 0; }","exercise":"یک نشان کوچک را در گوشه بالای کارت با position قرار بده.","sort_order":11},{"id":"css:12","course_id":"css","title":"CSS Grid","content_html":"<p>Grid برای چیدمان دوبعدی ردیف و ستون مناسب است. با grid-template-columns ستون‌ها و با gap فاصله خانه‌ها را تعیین می‌کنی. repeat و minmax ساخت شبکه‌های منعطف را آسان می‌کنند.</p>","starter_code":".grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 16px;\n}\n@media (max-width: 650px) {\n  .grid { grid-template-columns: 1fr; }\n}","exercise":"یک شبکه سه‌ستونه بساز و فاصله بین کارت‌ها را تنظیم کن.","sort_order":12},{"id":"css:13","course_id":"css","title":"شبه‌کلاس‌ها","content_html":"<p>شبه‌کلاس‌ها وضعیت عنصر را هدف می‌گیرند. :hover هنگام قرار گرفتن نشانگر، :focus هنگام دریافت تمرکز و :first-child برای اولین فرزند کاربرد دارند. برای کاربران صفحه‌کلید، حالت focus را حذف نکن.</p>","starter_code":"a:hover { color: crimson; }\ninput:focus { outline: 2px solid crimson; }\nli:first-child { font-weight: bold; }","exercise":"برای لینک حالت hover و برای ورودی حالت focus تعریف کن.","sort_order":13},{"id":"css:14","course_id":"css","title":"شبه‌عنصرها","content_html":"<p>شبه‌عنصرهایی مانند ::before و ::after بخشی مجازی برای نمایش تزئینات ایجاد می‌کنند. برای محتوای مهم و ضروری به آن‌ها تکیه نکن؛ چون هدف اصلی‌شان ارائه ظاهری است.</p>","starter_code":".title::after {\n  content: '';\n  display: block;\n  width: 50px;\n  height: 3px;\n  background: crimson;\n}","exercise":"با ::before یک نشان تزئینی پیش از عنوان ایجاد کن.","sort_order":14},{"id":"css:15","course_id":"css","title":"رنگ، شفافیت و سایه","content_html":"<p>برای رنگ می‌توان از HEX، rgb و hsl استفاده کرد. opacity شفافیت کل عنصر و box-shadow سایه جعبه را کنترل می‌کند. برای متن، کنتراست کافی با پس‌زمینه ضروری است.</p>","starter_code":".card {\n  color: #222;\n  background: rgba(255,255,255,.95);\n  box-shadow: 0 8px 24px rgba(0,0,0,.15);\n}","exercise":"برای کارت پس‌زمینه نیمه‌شفاف و سایه ملایم بساز.","sort_order":15},{"id":"css:16","course_id":"css","title":"انتقال و تبدیل","content_html":"<p>transition تغییر ویژگی را نرم می‌کند و transform عنصر را جابه‌جا، چرخان یا بزرگ و کوچک می‌کند. فقط ویژگی‌هایی را متحرک کن که تجربه کاربر را بهتر می‌کنند.</p>","starter_code":".button { transition: transform .2s, background .2s; }\n.button:hover { transform: translateY(-2px); }","exercise":"با hover کارت را کمی بزرگ کن و تغییر را با transition نرم کن.","sort_order":16},{"id":"css:17","course_id":"css","title":"متغیرهای CSS","content_html":"<p>متغیرهای سفارشی با دو خط تیره تعریف می‌شوند و با var خوانده می‌شوند. آن‌ها برای رنگ‌های برند، فاصله‌ها و تنظیمات مشترک بسیار مفیدند.</p>","starter_code":":root {\n  --brand: #e32636;\n  --space: 16px;\n}\n.button { background: var(--brand); padding: var(--space); }","exercise":"رنگ اصلی را در :root تعریف کن و در دو عنصر استفاده کن.","sort_order":17},{"id":"js:0","course_id":"js","title":"JavaScript چیست؟","content_html":"<p>JavaScript زبان برنامه‌نویسی است که می‌تواند به صفحه وب رفتار اضافه کند؛ مثل واکنش به کلیک، محاسبه و تغییر محتوا.</p>","starter_code":"console.log('سلام از JavaScript!');","exercise":"با console.log یک پیام خوش‌آمدگویی در کنسول نمایش بده.","sort_order":0},{"id":"js:1","course_id":"js","title":"متغیرها","content_html":"<p>برای نگهداری داده از let و const استفاده می‌کنیم. مقدار const دوباره به متغیر نسبت داده نمی‌شود؛ let برای مقداری است که ممکن است تغییر کند.</p>","starter_code":"const academy = 'NEXORA';\nlet lessons = 6;\nlessons = 7;\nconsole.log(academy, lessons);","exercise":"نام آکادمی را با const و تعداد درس‌ها را با let ذخیره و چاپ کن.","sort_order":1},{"id":"js:2","course_id":"js","title":"نوع داده‌ها","content_html":"<p>رشته، عدد، مقدار بولی، آرایه و شیء از انواع داده رایج هستند. typeof نوع بسیاری از مقدارها را نشان می‌دهد.</p>","starter_code":"const name = 'Ali';\nconst age = 18;\nconst active = true;\nconsole.log(typeof name);\nconsole.log(typeof age);","exercise":"یک رشته، عدد، مقدار بولی، آرایه و شیء بساز و نوع داده‌ها را بررسی کن.","sort_order":2},{"id":"js:3","course_id":"js","title":"شرط‌ها","content_html":"<p>با if و else می‌توان بر اساس درست یا نادرست بودن یک شرط مسیرهای متفاوتی اجرا کرد. برای مقایسه مقدار و نوع، معمولاً از === استفاده کن.</p>","starter_code":"const score = 75;\nif (score >= 50) {\n  console.log('قبول شدی');\n} else {\n  console.log('بیشتر تمرین کن');\n}","exercise":"بر اساس نمره، پیام قبولی یا نیاز به تمرین نمایش بده.","sort_order":3},{"id":"js:4","course_id":"js","title":"تابع‌ها","content_html":"<p>تابع مجموعه‌ای از دستورهاست که می‌توان آن را دوباره اجرا کرد. تابع می‌تواند ورودی بگیرد و با return نتیجه برگرداند.</p>","starter_code":"function greet(name) {\n  return 'سلام ' + name;\n}\nconsole.log(greet('دوست من'));","exercise":"تابعی بنویس که نام را بگیرد و پیام خوش‌آمدگویی برگرداند.","sort_order":4},{"id":"js:5","course_id":"js","title":"رویداد کلیک","content_html":"<p>رویدادها به ما اجازه می‌دهند به کار کاربر واکنش نشان دهیم. در این مثال با کلیک روی دکمه، متن صفحه تغییر می‌کند.</p>","starter_code":"<button id=\"helloBtn\">کلیک کن</button>\n<p id=\"message\"></p>\n<script>\ndocument.querySelector('#helloBtn').addEventListener('click', () => {\n document.querySelector('#message').textContent = 'آفرین!';\n});\n<\\/script>","exercise":"با کلیک روی دکمه، متن یک پاراگراف را تغییر بده.","sort_order":5},{"id":"js:6","course_id":"js","title":"عملگرهای ریاضی و مقایسه","content_html":"<p>عملگرهای +، -، * و / محاسبه می‌کنند. عملگرهای ===، !==، بزرگ‌تر و کوچک‌تر برای مقایسه‌اند. برای مقایسه مقدار و نوع، از مقایسه سخت‌گیرانه استفاده کن.</p>","starter_code":"const price = 120;\nconst count = 3;\nconsole.log(price * count);\nconsole.log(count >= 2);\nconsole.log(5 === '5'); // false","exercise":"دو عدد را با عملگرهای +، * و === مقایسه و نتیجه را چاپ کن.","sort_order":6},{"id":"js:7","course_id":"js","title":"عملگرهای منطقی","content_html":"<p>عملگر && وقتی هر دو شرط درست باشند نتیجه درست می‌دهد؛ || وقتی دست‌کم یکی درست باشد و ! مقدار منطقی را برعکس می‌کند.</p>","starter_code":"const age = 20;\nconst hasTicket = true;\nconsole.log(age >= 18 && hasTicket);\nconsole.log(!hasTicket);","exercise":"شرطی بنویس که فقط در صورت درست بودن دو شرط پیام دسترسی بدهد.","sort_order":7},{"id":"js:8","course_id":"js","title":"حلقه for","content_html":"<p>حلقه for برای تکرار تعداد مشخصی از دفعات مناسب است. بخش آغاز، شرط ادامه و تغییر شمارنده در سرآیند حلقه نوشته می‌شوند.</p>","starter_code":"for (let i = 1; i <= 5; i++) {\n  console.log('شماره ' + i);\n}","exercise":"اعداد ۱ تا ۱۰ را با حلقه for در کنسول چاپ کن.","sort_order":8},{"id":"js:9","course_id":"js","title":"حلقه while و کنترل تکرار","content_html":"<p>while تا زمانی اجرا می‌شود که شرط درست باشد. مراقب باش شرط در نهایت نادرست شود؛ وگرنه حلقه بی‌نهایت ایجاد می‌شود. break حلقه را متوقف و continue به تکرار بعدی می‌رود.</p>","starter_code":"let number = 1;\nwhile (number <= 5) {\n  console.log(number);\n  number++;\n}","exercise":"با while تا رسیدن شمارنده به ۵ ادامه بده و سپس متوقف شو.","sort_order":9},{"id":"js:10","course_id":"js","title":"آرایه‌ها","content_html":"<p>آرایه چند مقدار را در یک متغیر نگه می‌دارد. اندیس آرایه از صفر شروع می‌شود؛ length تعداد عناصر را می‌دهد و می‌توان با اندیس به یک عضو دسترسی داشت.</p>","starter_code":"const skills = ['HTML', 'CSS', 'JavaScript'];\nconsole.log(skills[0]);\nconsole.log(skills.length);","exercise":"آرایه‌ای از سه نام درس بساز و عضو اول و آخر را چاپ کن.","sort_order":10},{"id":"js:11","course_id":"js","title":"افزودن و حذف از آرایه","content_html":"<p>push عضو را به انتها اضافه و pop عضو آخر را حذف می‌کند. unshift به ابتدا اضافه و shift عضو اول را حذف می‌کند. این روش‌ها آرایه اصلی را تغییر می‌دهند.</p>","starter_code":"const tasks = ['مطالعه'];\ntasks.push('تمرین');\ntasks.pop();\nconsole.log(tasks);","exercise":"یک درس به انتهای آرایه اضافه و سپس آخرین عضو را حذف کن.","sort_order":11},{"id":"js:12","course_id":"js","title":"پیمایش آرایه با forEach","content_html":"<p>forEach یک تابع را برای هر عضو آرایه اجرا می‌کند. این روش برای انجام کاری روی هر عضو مناسب است و آرایه جدید برنمی‌گرداند.</p>","starter_code":"const names = ['سارا', 'علی', 'مینا'];\nnames.forEach(name => {\n  console.log('سلام ' + name);\n});","exercise":"نام هر عضو آرایه را با forEach در کنسول چاپ کن.","sort_order":12},{"id":"js:13","course_id":"js","title":"متد map و filter","content_html":"<p>map از هر عضو آرایه مقداری می‌سازد و آرایه جدید برمی‌گرداند. filter فقط عضوهایی را نگه می‌دارد که شرط را بگذرانند؛ هر دو آرایه اصلی را دست‌نخورده می‌گذارند.</p>","starter_code":"const numbers = [1, 2, 3, 4];\nconst doubled = numbers.map(n => n * 2);\nconst even = numbers.filter(n => n % 2 === 0);\nconsole.log(doubled, even);","exercise":"از آرایه نمره‌ها با map نمره‌ها را دو برابر و با filter نمره‌های بالای ۵۰ را جدا کن.","sort_order":13},{"id":"js:14","course_id":"js","title":"شیءها","content_html":"<p>شیء داده‌ها را به شکل ویژگی و مقدار نگه می‌دارد. به ویژگی‌ها با نقطه یا براکت دسترسی پیدا می‌کنی. برای داده‌های مرتبط، شیء ساختار روشنی ایجاد می‌کند.</p>","starter_code":"const student = {\n  name: 'مریم',\n  age: 19,\n  active: true\n};\nconsole.log(student.name);\nstudent.age = 20;","exercise":"شیئی برای دانش‌آموز با name، age و course بساز و مقدارها را بخوان.","sort_order":14},{"id":"js:15","course_id":"js","title":"توابع پیکانی و پارامتر پیش‌فرض","content_html":"<p>تابع پیکانی شکل کوتاه‌تری برای تعریف تابع است. می‌توان برای پارامتر مقدار پیش‌فرض گذاشت تا اگر ورودی ارسال نشد از آن استفاده شود.</p>","starter_code":"const greet = (name = 'دوست') => {\n  return 'سلام ' + name;\n};\nconsole.log(greet());\nconsole.log(greet('سارا'));","exercise":"تابع پیکانی بساز که اگر نامی داده نشد، مقدار پیش‌فرض استفاده کند.","sort_order":15},{"id":"js:16","course_id":"js","title":"انتخاب عناصر صفحه با DOM","content_html":"<p>DOM نمای درختی صفحه است. با querySelector اولین عنصر مطابق انتخابگر و با querySelectorAll همه موارد مطابق را پیدا می‌کنی. سپس می‌توان متن یا ویژگی‌های آن‌ها را تغییر داد.</p>","starter_code":"const heading = document.querySelector('h1');\nif (heading) {\n  heading.textContent = 'عنوان تازه';\n}","exercise":"با querySelector عنوان صفحه را پیدا کن و متنش را تغییر بده.","sort_order":16},{"id":"js:17","course_id":"js","title":"رویدادها و event","content_html":"<p>با addEventListener به رویدادهایی مثل click و input گوش می‌دهیم. شیء event اطلاعات رویداد را دارد و currentTarget عنصری را نشان می‌دهد که شنونده روی آن نصب شده است.</p>","starter_code":"const button = document.querySelector('button');\nbutton.addEventListener('click', event => {\n  event.currentTarget.textContent = 'کلیک شد';\n});","exercise":"رویداد کلیک را ثبت کن و نوع رویداد را از شیء event بخوان.","sort_order":17},{"id":"js:18","course_id":"js","title":"کار با فرم و ورودی کاربر","content_html":"<p>برای دریافت مقدار ورودی از value استفاده کن. رویداد submit فرم را می‌توان کنترل کرد و با preventDefault از بارگذاری دوباره صفحه جلوگیری کرد. داده کاربر را قبل از استفاده بررسی کن.</p>","starter_code":"const form = document.querySelector('form');\nform.addEventListener('submit', event => {\n  event.preventDefault();\n  const name = document.querySelector('#name').value.trim();\n  console.log(name);\n});","exercise":"با submit مقدار ورودی را بخوان و از بارگذاری دوباره صفحه جلوگیری کن.","sort_order":18},{"id":"js:19","course_id":"js","title":"اعتبارسنجی ساده فرم","content_html":"<p>اعتبارسنجی یعنی بررسی اینکه داده ورودی قابل قبول است. برای ایمیل و فیلدهای ضروری می‌توان از ویژگی‌های HTML مثل required و type استفاده کرد و در JavaScript پیام دقیق‌تری نمایش داد.</p>","starter_code":"const username = 'Nexora';\nif (username.trim().length < 3) {\n  console.log('نام باید حداقل ۳ حرف باشد');\n} else {\n  console.log('نام معتبر است');\n}","exercise":"بررسی کن ورودی خالی نباشد و ایمیل شامل @ باشد.","sort_order":19},{"id":"js:20","course_id":"js","title":"ذخیره‌سازی در localStorage","content_html":"<p>localStorage داده متنی را در مرورگر همان دستگاه نگه می‌دارد و پس از بستن صفحه باقی می‌ماند. این داده به‌صورت خودکار بین دستگاه‌ها همگام نمی‌شود و برای رمز عبور یا اطلاعات حساس مناسب نیست.</p>","starter_code":"localStorage.setItem('theme', 'dark');\nconst theme = localStorage.getItem('theme');\nconsole.log(theme);\n// localStorage.removeItem('theme');","exercise":"نام کاربر را ذخیره کن و در بارگذاری بعدی بخوان.","sort_order":20},{"id":"js:21","course_id":"js","title":"JSON و تبدیل داده","content_html":"<p>JSON قالبی متنی برای تبادل داده است. JSON.stringify شیء را به متن تبدیل می‌کند و JSON.parse متن معتبر JSON را به داده JavaScript تبدیل می‌کند.</p>","starter_code":"const user = { name: 'Ali', level: 1 };\nconst text = JSON.stringify(user);\nconst copy = JSON.parse(text);\nconsole.log(copy.name);","exercise":"یک شیء را با JSON.stringify به متن و با JSON.parse به شیء تبدیل کن.","sort_order":21},{"id":"js:22","course_id":"js","title":"مدیریت خطا با try و catch","content_html":"<p>گاهی اجرای یک دستور با خطا روبه‌رو می‌شود. try کد پرخطر را در بر می‌گیرد و catch خطا را دریافت می‌کند تا برنامه بتواند واکنش کنترل‌شده نشان دهد.</p>","starter_code":"try {\n  const data = JSON.parse('{bad json}');\n  console.log(data);\n} catch (error) {\n  console.log('داده معتبر نیست');\n}","exercise":"تبدیل یک متن نامعتبر JSON را در try/catch قرار بده و پیام خطا را نمایش بده.","sort_order":22},{"id":"js:23","course_id":"js","title":"تاریخ و زمان","content_html":"<p>شیء Date برای کار با تاریخ و زمان استفاده می‌شود. getFullYear سال و getMonth ماه را از صفر تا یازده برمی‌گرداند؛ برای نمایش ماه انسانی معمولاً یک واحد اضافه می‌کنیم.</p>","starter_code":"const now = new Date();\nconsole.log(now.getFullYear());\nconsole.log(now.getMonth() + 1);\nconsole.log(now.toLocaleDateString('fa-IR'));","exercise":"تاریخ و ساعت فعلی را با شیء Date نمایش بده.","sort_order":23},{"id":"js:24","course_id":"js","title":"پروژه کوچک: شمارنده","content_html":"<p>در این تمرین یک شمارنده می‌سازیم. متغیر count وضعیت را نگه می‌دارد و هر کلیک مقدار را یک واحد افزایش می‌دهد. در پروژه واقعی، HTML دکمه و خروجی باید در صفحه وجود داشته باشند.</p>","starter_code":"let count = 0;\nconst button = document.querySelector('#plus');\nconst output = document.querySelector('#count');\nbutton.addEventListener('click', () => {\n  count++;\n  output.textContent = count;\n});","exercise":"شمارنده‌ای با دکمه‌های افزایش، کاهش و صفرکردن بساز.","sort_order":24}]$academy_seed$::jsonb)
 as x(id text,course_id text,title text,content_html text,starter_code text,exercise text,sort_order int)
)
insert into public.academy_lessons(id,course_id,title,content_html,starter_code,exercise,sort_order,is_published)
select id,course_id,title,content_html,starter_code,exercise,sort_order,true from seed
on conflict(id) do update set
 course_id=excluded.course_id,title=excluded.title,content_html=excluded.content_html,
 starter_code=excluded.starter_code,exercise=excluded.exercise,sort_order=excluded.sort_order;
